import { PluginObject } from 'vue';
import { coreFeatures } from './core-features';
import { queryStringParams } from '../services/query-string';
import { IGamePref, ISessionDataJustification } from '../types';
import { IAdditionalSettingsItem } from '../views/settings-menu/types';

export interface IGameFeatures {
    swipeToBuy?: boolean;
    colourBlindMode?: boolean;
    newStyleHTP?: boolean;
    maxAutoBuys?: number;
    showSessionData?: boolean;
    sessionDataJustification?: ISessionDataJustification;
    enableSessionManager?: boolean;
    showSessionStatusInSettings?: boolean;
    seperateMusicSoundControls?: boolean;
    usingLocalAssets?: boolean;
    initialBalanceCheck?: { shouldCheckBalance: boolean, minBalance: number; };
    engineRequiresSkinParam?: boolean;
    batchLoadAssets?: boolean;
    supportsFreeplays?: boolean;
    freePlayExcludedSkins?: string[];
    syncSessionWithParent?: boolean;
    enableActionMenu?: boolean;
    enableGameInGame?: boolean;
    enableLobby?: boolean;
    enablePrizeLeague?: boolean;
    enableSettings?: boolean;
    enableCompanionPanel?: boolean;
    enableChat?: boolean;
    canHideChat?: boolean;
}

export interface ICoreFeatures {
    showChatUserList: boolean;
    useWalletBalance: boolean;
}

export type EngineName = string | { url: string; skin: string; };
export interface IEngineConfig {
    /** Category/Lobby that the game belongs too */
    GameCategory: string;
    /** Game Guid from the config portal (https://tools.tombolagamestudio.com/). Used to uniquely identify the game to check against configurations */
    GameGuid: string;
    /** Name setup by the Engine Team */
    EngineName: EngineName | undefined;
    /** Optional name of the endpoint to use when retrieving the recent winners list. Defaults to GameCategory if not specified */
    RecentWinnersName?: string;
    /** Name to be put at the start of any logging */
    LoggingName: string;
    /** Version of the game - Should come from package.json */
    Version: string;
    /** Numerical representation of the ratio of the games height relative to it's width: { 0.67 = 16:9 - 0.83 = 4:3 } */
    HeightRatio: number;
    /** Optional toggle to maintain height ratio when the game is a sub-game */
    MaintainHeightRatioAsSubGame?: boolean;
    /** Maximum percentage of screen height */
    HeightLimit?: number;
    /** How big the win has to be to trigger the big win  */
    BigWinStakeMultiplier?: number;

    /** How many errors that can be tracked in the debug menu  */
    ErrorsToTrack?: number;

    /** function that returns an array of IAdditionalSettingsItem, additional options wanted in the mobile-web settings list **DOES NOT APPLY TO APPS */
    AdditionalSettingsGetter?: () => IAdditionalSettingsItem[];
    /** Any additional preferences you want stored in localSTorage with the userPrefs */
    GamePreferences: Record<string, IGamePref>;

    /** Path for the font css file within the game folder structure */
    FontCSSFilepath?: string;

    /** Name of the folder on cdn under clients/mobile/arcade/assets/en_GB */
    CdnFolderName: string;

    /** Version of the Core Folder on the CDN. Used for loading the strings.json */
    LegacyCoreVersion?: string;

    /** Feature list - see IGameFeatures for options */
    Features: IGameFeatures;

    /** Optional bool to prevent the game auto running after initialisation so we can do something else first if needed */
    AutoRun?: boolean;
    /** Optional bool to not send a resume request on load, useful for free games like match-to-win */
    IgnoreResumeData?: boolean;

    /** Optional Core Feature list override */
    CoreFeatures?: ICoreFeatures;

    /** Optional Vue plugin to be used with the game, can be used to override default overlays or register additional vue components */
    VuePlugin?: PluginObject<void>;

    /**
     * Optional: Defines the folder in the game for this skins assets.
     * 
     * Useful for sharing asset folders across "skins" i.e. normal and jackpots
     * 
     * Default: queryStringParams.currentSkin
     * */
    AssetFolder?: string;

    /**
     * Optional: override the chat name that is used by chat. 
     * 
     * Useful if the skin has the same name as an existing game or skin.
     * 
     * Default: queryStringParams.currentSkin
     */
    ChatName?: Record<string, string>;

    /**
     * Optional: overrides the international chat api endpoint to /{queryStringParams.currentSkin} instead of using /arcade.
     * 
     * All skins point to /arcade by default however some mechanics or skins may want to point to a different end point if they want separate rooms from the standard. 
     * You would need to configure each skin name on swagger if you were to use this.
     * 
     * Default: 'queryStringParams.currentSkin'
     */
    SkinSpecificChatRoom?: boolean;
}

export class GameConfig {
    public static get Instance(): GameConfig { return this._instance || (this._instance = new GameConfig()); }
    private static _instance: GameConfig;

    public assetQuality: string = 'unset';
    public usingCdnStrings: boolean = false;

    private _fontCSSFilepath: string = './static/fonts/fonts-v2.css';

    private _cdnFolderName: string = 'unset';
    private _engineName: string = 'unset';
    private _engineSkinName: string = 'unset';
    private _assetFolder: string = 'unset';
    private _legacyCoreVersion: string | undefined;
    private _recentWinnersName: string | undefined;
    private _gameCategory: string = 'unset';
    private _gameGuid: string = 'unset';
    private _loggingName: string = 'unset';
    private _version: string = 'unset';
    private _chatName: string = 'unset';
    private _skinSpecificChatRoom: boolean = false;

    private _heightLimit: number = -1;
    private _appHeightRatio: number = -1;
    private _defaultHeightRatio: number = -1;
    private _heightRatio: number = -1;
    private _maintainHeightRatioAsSubGame: boolean = true;
    private _bigWinStakeMultiplier: number = 15;

    private _errorsToTrack: number = 20;

    private _ignoreResumeData: boolean = false;

    private _batchLoadAssets: boolean = true;

    private _features: Required<IGameFeatures> = {
        swipeToBuy: false,
        colourBlindMode: false,
        newStyleHTP: false,
        maxAutoBuys: 0,
        showSessionData: true,
        sessionDataJustification: {
            portrait: 'default',
            landscape: 'default'
        },
        enableSessionManager: false,
        showSessionStatusInSettings: false,
        seperateMusicSoundControls: true,
        usingLocalAssets: false,
        initialBalanceCheck: { shouldCheckBalance: false, minBalance: 0 },
        engineRequiresSkinParam: true,
        batchLoadAssets: false,
        supportsFreeplays: true,
        freePlayExcludedSkins: [],
        syncSessionWithParent: true,
        enableActionMenu: true,
        enableGameInGame: false,
        enableLobby: false,
        enablePrizeLeague: false,
        enableSettings: false,
        enableChat: true,
        canHideChat: false,
        enableCompanionPanel: true
    };

    private _coreFeatures: Required<ICoreFeatures> = {
        showChatUserList: coreFeatures[queryStringParams.locale].showChatUserList ?? coreFeatures['en-gb'].showChatUserList,
        useWalletBalance: coreFeatures[queryStringParams.locale].useWalletBalance ?? coreFeatures['en-gb'].useWalletBalance
    };

    private _gamePrefs: Record<string, IGamePref> = {};

    private _additionalSettingsGetter: (() => IAdditionalSettingsItem[]) | undefined;

    private constructor() { }

    public get chatName(): string {
        return this._chatName;
    }

    public get skinSpecificChatRoom(): boolean {
        return this._skinSpecificChatRoom;
    }

    public get batchLoadAssets(): boolean {
        return this._batchLoadAssets;
    }

    public get fontCSSFilepath(): string {
        return this._fontCSSFilepath;
    }

    public get cdnFolderName(): string {
        return this._cdnFolderName;
    }

    public get legacyCoreVersion(): string | undefined {
        return this._legacyCoreVersion;
    }

    public get engineName(): string {
        return this._engineName;
    }

    public get engineSkinName(): string {
        return this._engineSkinName;
    }

    public get assetFolder(): string {
        return this._assetFolder;
    }

    public get recentWinnersName(): string | undefined {
        return this._recentWinnersName;
    }

    public get gameCategory(): string {
        return this._gameCategory;
    }

    public get gameGuid(): string {
        return this._gameGuid;
    }

    public get loggingName(): string {
        return this._loggingName;
    }

    public get version(): string {
        return this._version;
    }

    public get appHeightRatio(): number {
        return this._appHeightRatio;
    }

    public get heightRatio(): number {
        return this._heightRatio;
    }

    public get heightLimit(): number {
        return this._heightLimit;
    }

    public get maintainHeightRatioAsSubGame(): boolean {
        return this._maintainHeightRatioAsSubGame;
    }

    public get bigWinStakeMultiplier(): number {
        return this._bigWinStakeMultiplier;
    }

    public get errorsToTrack(): number {
        return this._errorsToTrack;
    }

    public get gamePrefs(): Record<string, IGamePref> {
        return this._gamePrefs;
    }

    public get features(): Required<IGameFeatures> {
        return this._features;
    }

    public get coreFeatures(): Required<ICoreFeatures> {
        return this._coreFeatures;
    }

    public get additionalSettingsGetter(): (() => IAdditionalSettingsItem[]) {
        return this._additionalSettingsGetter ?? (() => []);
    }

    public get ignoreResumeData(): boolean {
        return this._ignoreResumeData;
    }

    public get supportsFreeplays(): boolean {
        if (this._features.supportsFreeplays === false) { return false; }

        const currentSkin = this._engineSkinName === 'unset' ? queryStringParams.currentSkin : this._engineSkinName;
        const match = this._features.freePlayExcludedSkins.find(entry => entry === currentSkin);
        return match ? false : true;
    }

    public setEngineName(name: EngineName): void {
        if (typeof name === 'string') {
            this._engineName = name;
            this._engineSkinName = queryStringParams.currentSkin;
        } else {
            this._engineName = name.url;
            this._engineSkinName = name.skin;
        }
    }

    public setChatName(config: IEngineConfig): void {
        this._chatName = 'arcade';
        
        if (config.SkinSpecificChatRoom) {
            this._chatName = queryStringParams.currentSkin;

            if (config.ChatName !== undefined) {
                this._chatName = config.ChatName[queryStringParams.currentSkin];
            }
        }
    }

    public apply(config: IEngineConfig): void {
        this._fontCSSFilepath = config.FontCSSFilepath || './static/fonts/fonts-v2.css';

        this._cdnFolderName = config.CdnFolderName;
        this._legacyCoreVersion = config.LegacyCoreVersion;
        this._recentWinnersName = config.RecentWinnersName;
        this._gameCategory = config.GameCategory;
        this._gameGuid = config.GameGuid;
        this._loggingName = config.LoggingName;
        this._version = config.Version;
        this.setChatName(config);
        this._skinSpecificChatRoom = config.SkinSpecificChatRoom ?? false;
        if (config.EngineName !== undefined) {
            this.setEngineName(config.EngineName);
        }

        this._assetFolder = config.AssetFolder ?? queryStringParams.currentSkin;

        this._heightRatio = config.HeightRatio;
        this._appHeightRatio = this._heightRatio;
        this._defaultHeightRatio = this._heightRatio;
        this._heightLimit = queryStringParams.isSubGame ? 100 : config.HeightLimit || 50;
        this._maintainHeightRatioAsSubGame = config.MaintainHeightRatioAsSubGame ?? true;

        this._bigWinStakeMultiplier = config.BigWinStakeMultiplier || 15;
        this._errorsToTrack = config.ErrorsToTrack || 20;

        this._gamePrefs = config.GamePreferences;

        this._ignoreResumeData = config.IgnoreResumeData || false;

        for (const key in config.Features) {
            if (key in this._features) {
                const feature = config.Features[key as keyof IGameFeatures];
                if (feature !== undefined) {
                    (this._features[key as keyof IGameFeatures] as typeof feature) = feature;
                }
            } else {
                console.error(`Key: ${key} found in config.Features but does not exist in the config-model\nValid keys include: ${Object.keys(this._features).toString()}`);
            }
        }

        for (const key in config.CoreFeatures) {
            if (key in this._coreFeatures) {
                const feature = config.CoreFeatures[key as keyof ICoreFeatures];
                if (feature !== undefined) {
                    (this._coreFeatures[key as keyof ICoreFeatures] as typeof feature) = feature;
                }
            } else {
                console.error(`Key: ${key} found in config.CoreFeatures but does not exist in the config-model\nValid keys include: ${Object.keys(this._coreFeatures).toString()}`);
            }
        }

        if (config.Features.enableCompanionPanel === undefined) {
            this._features.enableCompanionPanel = this._features.enableChat;
        }

        if (queryStringParams.isSubGame === true) {
            // disable the whole action menu for game-in-game setup
            this._features.enableActionMenu = false;
            this._features.enableChat = false;
            this._features.enableGameInGame = false;
            this._features.enablePrizeLeague = false;
            // disables the spain session manager entirely for sub games as the parent handles it
            this._features.enableSessionManager = false;
        }

        if (config.AdditionalSettingsGetter) {
            this._additionalSettingsGetter = config.AdditionalSettingsGetter;
        }
    }
}

export const gameConfig = GameConfig.Instance;